import {bodyPages,bodyCatalog,bodyLegOptions,bodyFeatureChoices} from './body-clues-content.mjs';
import {bodyView,startBody,setBodyPage,setBodyView,chooseBodyLegs,chooseBodyFeature,addBodySupport,resumeBody,checkBody,bodyCheckMatches} from './body-clues-core.mjs';
import {bodyDiagram} from './body-clues-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const legLabel=id=>bodyLegOptions.find(x=>x.id===id)?.label||id;
const featureLabel=(source,id,legs)=>id===null?'No second clue':id==='other'?'Something else':id==='unsure'?'I cannot tell':source.key.find(k=>k.legs===legs&&k.body===id)?.clue||id;
const comparison=value=>value===null?'not observed':value?'matches the supplied diagram':'differs from the supplied diagram';
function viewChoices(r){return `<div class="body-choices" role="group" aria-label="Diagram view">${[['body','Body view'],['detail','Walking-leg detail']].map(([id,label])=>button(`data-body-view="${id}" aria-pressed="${r.view===id}"`,`${label}${r.view===id?' · open':''}`,r.view===id)).join('')}</div>`;}
function reference(source){return `<details id="body-reference"><summary>Our ${source.key.length}-picture key</summary><p class="tiny">This key names only these supplied adult pictures. Zero jointed walking legs still needs a second clue.</p><ul>${source.key.map(k=>`<li><strong>${esc(k.legs)} jointed walking legs</strong> + ${esc(k.clue)}: ${esc(k.label)}</li>`).join('')}</ul></details>`;}
function frozenSource(source){return `<details class="body-frozen-source"><summary>Picture and clues kept with this trail</summary><p><strong>${esc(source.title)}</strong> · ${esc(source.label)} · pictured adult</p>${bodyDiagram(source,'body')}${bodyDiagram(source,'detail')}<p>${esc(source.inspection)}</p><p>${esc(source.bodyText)}</p><p>${esc(source.detailText)}</p><p>${esc(source.help)}</p><ul>${source.key.map(k=>`<li>${esc(k.legs)} jointed walking legs + ${esc(k.clue)}: ${esc(k.label)}</li>`).join('')}</ul></details>`;}
function record(r,c,index,notes=false){return `<section class="body-record" tabindex="-1"><h3>${index===r.checks.length-1&&bodyCheckMatches(r,c)?'Latest kept trail for these choices':'Earlier recorded trail'}</h3><p><strong>Chosen trail:</strong> ${esc(legLabel(c.input.legs))} jointed walking legs; ${esc(featureLabel(c.source,c.input.feature,c.input.legs))}.</p><p><strong>Recorded key result:</strong> ${c.named?`This trail names ${esc(c.named.label)}.`:c.stop==='outside'?`This trail stops outside our ${c.source.key.length}-picture key.`:c.stop==='unclear'?'This trail stops for a clearer look.':'No name or stop reason recorded.'}</p><p><strong>Recorded leg clue:</strong> ${comparison(c.features.legs)}.<br><strong>Recorded body clue:</strong> ${comparison(c.features.body)}.</p><p class="body-feedback">${esc(c.feedback)}</p>${notes?`<p>Support requested by this check: ${Object.hasOwn(c,'support')?esc(c.support.join(', ')||'none recorded'):'not recorded in this earlier check'}. This does not establish independence.</p>`:''}${frozenSource(c.source)}</section>`;}
function inspect(r){return `<h2 id="body-prompt" tabindex="-1">What body clues can we notice?</h2>${viewChoices(r)}${bodyDiagram(r.source,r.view)}<p>${esc(r.source.inspection)}</p>${hearButton(r.view==='body'?r.source.bodyText:r.source.detailText,'Hear the diagram description')}${button('data-body-page="key"','Follow the key',true)}<p class="tiny">A supplied adult teaching diagram, not a real animal observation. Body and detail show the same picture.</p>`;}
function keyPage(r){const features=bodyFeatureChoices(r.source,r.legs),ready=r.legs!==null&&(!features.length||r.feature!==null);return `<h2 id="body-prompt" tabindex="-1">Follow two body clues</h2><div class="body-key-layout"><section class="body-key-picture" aria-label="Current picture and view">${viewChoices(r)}${bodyDiagram(r.source,r.view)}<details id="body-diagram-guide" data-round="${r.id}"><summary>Diagram description and leg guide</summary><p>${esc(r.view==='body'?r.source.bodyText:r.source.detailText)}</p><p>Jointed walking legs use thick green strokes with visible joints. Thin ochre feelers and tentacles are not walking legs. A muscular foot and body rings are not walking legs. Other appendages are outside this walking-leg count.</p>${hearButton(r.view==='body'?r.source.bodyText:r.source.detailText,'Hear the diagram description')}</details></section><section class="body-key-questions" aria-label="Choose a key trail"><fieldset><legend>How many jointed walking legs can we see in the detail?</legend><div class="body-choices" role="group" aria-label="Jointed walking leg count">${bodyLegOptions.map(o=>button(`data-body-legs="${o.id}" aria-pressed="${r.legs===o.id}"`,`${o.label}${r.legs===o.id?' · selected':''}`,r.legs===o.id)).join('')}</div></fieldset>${features.length?`<fieldset><legend>Which body clue can we see?</legend><div class="body-feature-choices" role="group" aria-label="Second body clue">${features.map(o=>button(`data-body-feature="${o.id}" aria-pressed="${r.feature===o.id}"`,`${o.label}${r.feature===o.id?' · selected':''}`,r.feature===o.id)).join('')}</div></fieldset>`:r.legs==='other'?`<p>This is outside our ${r.source.key.length}-picture key. We do not need a second question.</p>`:r.legs==='unsure'?'<p>We need a clearer look before choosing a branch. No leg count has been inferred.</p>':'<p>Choose a leg clue to see the next question. “I cannot tell” is welcome.</p>'}${button(`data-body-check${ready?'':' disabled'}`,'Keep this trail',true)}<p class="tiny">Up to 8 trails stay in this picture visit. Keeping a ninth removes the oldest trail.</p></section></div>${reference(r.source)}`;}
function keep(r){const c=r.checks.at(-1);return `<h2 id="body-prompt" tabindex="-1">Our revisable picture trail</h2>${c?record(r,c,r.checks.length-1):'<p>No trail has been kept yet. The same picture and your choices are waiting in the key.</p>'}${button('data-body-page="key"','Change our trail',true)} ${button('data-body-page="inspect"','Inspect the same picture')}<p class="tiny">A key name and agreement with this picture are separate. This is practice with four supplied adults, not field identification.</p>`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="body-catalog"><h2>Choose another picture</h2><p>Any of these ${bodyCatalog.length} pictures is open.</p><p class="tiny">Up to 12 readable picture visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Starting a picture keeps earlier visits within that limit.'}</p><div class="body-catalog-choices">${bodyCatalog.map(source=>button(`data-body-start="${source.id}"`,source.title)).join('')}</div></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our picture visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-body-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}${v.current?.id===r.id?' · open':''}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>This original work stays unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function bodyCluesPage(state){const v=bodyView(state),r=v.current,heading=`<header class="page-heading"><a class="back" href="#living">← Living Garden</a><h1>Body clues</h1><p>The crew is making labels for a wildlife corner. Look at a pictured adult, then follow our ${bodyCatalog.length}-picture key.</p><p class="body-movement-entry"><a class="secondary" href="#living/movement">How can two animals move without jointed walking legs? Step a snail and an earthworm model together.</a></p></header>`;if(v.status==='unavailable')return `<div class="body-page">${heading}<section class="body-sheet"><h2>Earlier work is safe</h2><p>This saved body-clue work uses a format we cannot continue here. It stays unchanged; the Living Garden remains open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.bodyClues,null,2))}</pre></details></section></div>`;return `<div class="body-page">${heading}<section class="body-sheet"><nav class="body-tabs" aria-label="Body-clue pages">${bodyPages.map(p=>button(`data-body-page="${p}" aria-current="${v.page===p?'page':'false'}"`,p[0].toUpperCase()+p.slice(1),v.page===p)).join('')}</nav>${r?`<p class="body-picture-title"><strong>${esc(r.source.title)}</strong> · pictured adult${r.familiar?' · Familiar picture':''}</p>`:''}<p role="status" class="body-status" id="body-status" tabindex="-1"></p>${r?v.page==='key'?keyPage(r):v.page==='keep'?keep(r):inspect(r):`<h2 id="body-prompt" tabindex="-1">Which picture shall we inspect?</h2><p>We use jointed walking legs and a second body clue. Habitat alone does not tell us a name.</p>${catalog(v)}`}${r?`<details id="body-help" data-round="${r.id}"><summary>Help us follow the picture key</summary><p>${esc(r.source.help)}</p><p>${esc(r.source.inspection)}</p>${hearButton(r.source.help+' '+r.source.inspection,'Hear this help')}${button('data-body-together',r.support.includes('together')?'Exploring together recorded':'We explored together')}</details>${r.checks.length>1?`<details><summary>Earlier kept trails (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>record(r,c,i)).join('')}</details>`:''}<details><summary>Choose another picture</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function bodyCluesNotes(state){const v=bodyView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Body clues · earlier format</summary><pre>${esc(JSON.stringify(state.bodyClues,null,2))}</pre></details>`;return `<details class="panel body-page"><summary>Living Garden body clues (${v.rounds.length} picture visits)</summary><p>Original teaching diagrams and supplied picture keys. Key outcomes, feature comparisons and support requests are distinct. This does not establish field identification, independent observation, decoding or constructing a key. Body-clue actions add no habitat attempt, parcel or mathematical exposure; the existing host connection panel may still display/register incoming numerical facts on Living Garden routes.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Familiar picture: ${r.familiar?'yes':'no'}. Current support requests: ${esc(r.support.join(', ')||'none recorded')}.</p><p>Current draft: ${r.legs===null?'No leg clue':esc(legLabel(r.legs))}; ${esc(featureLabel(r.source,r.feature,r.legs))}.</p>${frozenSource(r.source)}${r.checks.map((c,i)=>record(r,c,i,true)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindBodyClues(state,{save,render,focus}){
 const show=(message='',target='#body-prompt')=>{const roundId=bodyView(state).current?.id,open=[...document.querySelectorAll('.body-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===roundId).map(d=>d.id);save();render();if(bodyView(state).current?.id===roundId)for(const id of open){const d=document.getElementById(id);if(d)d.open=true;}const status=document.querySelector('#body-status');if(status)status.textContent=message;focus?.(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 bind('[data-body-page]',b=>{const ok=setBodyPage(state,b.dataset.bodyPage);show(ok?'':'Choose a picture to begin.',ok?'#body-prompt':'#body-status');});
 bind('[data-body-start]',b=>{const r=startBody(state,b.dataset.bodyStart);show(r?'A new picture visit is ready. Earlier trails stay in their own visits.':'A new visit cannot be created because its saved visit numbers have reached the supported limit. Existing picture visits remain available.',r?'#body-prompt':'#body-status');});
 bind('[data-body-view]',b=>{setBodyView(state,b.dataset.bodyView);show('Diagram view changed; your chosen trail stays unchanged.',`[data-body-view="${b.dataset.bodyView}"]`);});
 bind('[data-body-legs]',b=>{chooseBodyLegs(state,b.dataset.bodyLegs);show('Leg clue selected. Choose its second clue if one is offered. Earlier trails stay unchanged.',`[data-body-legs="${b.dataset.bodyLegs}"]`);});
 bind('[data-body-feature]',b=>{chooseBodyFeature(state,b.dataset.bodyFeature);show('Body clue selected. Earlier kept trails stay unchanged.',`[data-body-feature="${b.dataset.bodyFeature}"]`);});
 bind('[data-body-check]',()=>{const c=checkBody(state);if(c)setBodyPage(state,'keep');show(c?'This trail and its separate feature comparisons are kept.':'Choose the leg clue and any required second clue before keeping.',c?'.body-record':'#body-status');});
 bind('[data-body-resume]',b=>{const ok=resumeBody(state,Number(b.dataset.bodyResume));show(ok?'Earlier picture visit opened. Its recorded trails stay unchanged.':'That picture visit could not be opened.');});
 bind('[data-body-together]',()=>{addBodySupport(state,'together');show('Exploring together recorded as optional support.','[data-body-together]');});
 const boundRoundId=bodyView(state).current?.id,help=document.querySelector('#body-help');
 help?.addEventListener('toggle',()=>{if(help.isConnected&&help.open&&Number(help.dataset.round)===boundRoundId&&bodyView(state).current?.id===boundRoundId){addBodySupport(state,'help');save();}});
 document.querySelectorAll('.body-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(b.isConnected&&boundRoundId!==undefined&&bodyView(state).current?.id===boundRoundId){addBodySupport(state,'audio');save();}}));
}
